package com.keystone.fieldservice.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity public class WorkOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String title; private String description; @Enumerated(EnumType.STRING) private WorkOrderStatus status = WorkOrderStatus.ASSIGNED; @ManyToOne private Site site; @ManyToOne private User assignedTo; private LocalDateTime createdAt = LocalDateTime.now(); public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getTitle(){return title;} public void setTitle(String t){this.title=t;} public String getDescription(){return description;} public void setDescription(String d){this.description=d;} public WorkOrderStatus getStatus(){return status;} public void setStatus(WorkOrderStatus s){this.status=s;} public Site getSite(){return site;} public void setSite(Site s){this.site=s;} public User getAssignedTo(){return assignedTo;} public void setAssignedTo(User u){this.assignedTo=u;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime c){this.createdAt=c;} }
